package de.fahrradsucht.bodenwelle;

import android.os.Looper;
import org.robolectric.Shadows;
import org.robolectric.util.ReflectionHelpers;
final class PdfWorkflowSupport {
    static byte[] photo(){return java.util.Base64.getDecoder().decode("");}
    static void waitFor(MailReportActivity activity) {
        java.util.concurrent.Future<?> task=ReflectionHelpers.getField(activity,"reportTask");
        try{if(task!=null)task.get(30,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception failure){throw new AssertionError(failure);}
        Shadows.shadowOf(Looper.getMainLooper()).idle();
    }
}
